**Auth service:**
<function_calls>
<invoke name="Write">
<parameter name="path">/tmp/chisle-ablate-work-vgAXU7/auth.js</parameter>
<parameter name="fileContents">const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const db = require('./db');

const JWT_SECRET = process.env.JWT_SECRET || 'dev-secret-change-in-prod';
const RATE_LIMIT_WINDOW = 15 * 60 * 1000; // 15 minutes
const MAX_ATTEMPTS = 5;
const LOCKOUT_DURATION = 30 * 60 * 1000; // 30 minutes

async function hashPassword(password) {
  return bcrypt.hash(password, 12);
}

async function verifyPassword(password, hash) {
  return bcrypt.compare(password, hash);
}

async function issueToken(userId) {
  return jwt.sign({ userId }, JWT_SECRET, { expiresIn: '7d' });
}

async function verifyToken(token) {
  try {
    return jwt.verify(token, JWT_SECRET);
  } catch (err) {
    return null;
  }
}

async function checkRateLimit(email) {
  const result = await db.query(
    'SELECT * FROM rate_limits WHERE email = $1',
    [email]
  );

  if (result.rows.length === 0) {
    return { allowed: true };
  }

  const record = result.rows[0];
  if (record.locked_until && new Date(record.locked_until) > new Date()) {
    return { allowed: false, reason: 'Account locked due to too many failed attempts' };
  }

  // Reset if window expired
  if (new Date() - new Date(record.created_at) > RATE_LIMIT_WINDOW) {
    await db.query('DELETE FROM rate_limits WHERE email = $1', [email]);
    return { allowed: true };
  }

  return { allowed: record.attempt_count < MAX_ATTEMPTS };
}

async function recordFailedAttempt(email) {
  const result = await db.query(
    'SELECT * FROM rate_limits WHERE email = $1',
    [email]
  );

  if (result.rows.length === 0) {
    await db.query(
      'INSERT INTO rate_limits (email, attempt_count, created_at) VALUES ($1, $2, NOW())',
      [email, 1]
    );
  } else {
    const record = result.rows[0];
    const newCount = record.attempt_count + 1;
    const lockoutUntil = newCount >= MAX_ATTEMPTS ? new Date(Date.now() + LOCKOUT_DURATION) : null;

    await db.query(
      'UPDATE rate_limits SET attempt_count = $1, locked_until = $2 WHERE email = $3',
      [newCount, lockoutUntil, email]
    );
  }
}

async function clearFailedAttempts(email) {
  await db.query('DELETE FROM rate_limits WHERE email = $1', [email]);
}

async function signup(email, password) {
  const passwordHash = await hashPassword(password);
  try {
    const result = await db.query(
      'INSERT INTO users (email, password_hash) VALUES ($1, $2) RETURNING id',
      [email, passwordHash]
    );
    const userId = result.rows[0].id;
    const token = await issueToken(userId);
    return { success: true, userId, token };
  } catch (err) {
    if (err.code === '23505') {
      return { success: false, reason: 'Email already registered' };
    }
    throw err;
  }
}

async function login(email, password) {
  const limitCheck = await checkRateLimit(email);
  if (!limitCheck.allowed) {
    return { success: false, reason: limitCheck.reason };
  }

  const result = await db.query(
    'SELECT * FROM users WHERE email = $1',
    [email]
  );

  if (result.rows.length === 0) {
    await recordFailedAttempt(email);
    return { success: false, reason: 'Invalid email or password' };
  }

  const user = result.rows[0];
  const passwordMatch = await verifyPassword(password, user.password_hash);

  if (!passwordMatch) {
    await recordFailedAttempt(email);
    return { success: false, reason: 'Invalid email or password' };
  }

  await clearFailedAttempts(email);
  const token = await issueToken(user.id);
  return { success: true, userId: user.id, token };
}

module.exports = { hashPassword, verifyPassword, issueToken, verifyToken, signup, login, checkRateLimit, recordFailedAttempt };
</parameter>
