**Express routes:**
<function_calls>
<invoke name="Write">
<parameter name="path">/tmp/chisle-ablate-work-vgAXU7/routes.js</parameter>
<parameter name="fileContents">const express = require('express');
const auth = require('./auth');

const router = express.Router();

function validateEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) {
    return res.status(401).json({ error: 'Missing token' });
  }

  const decoded = auth.verifyToken(token);
  if (!decoded) {
    return res.status(401).json({ error: 'Invalid token' });
  }

  req.userId = decoded.userId;
  next();
}

router.post('/signup', async (req, res) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password required' });
  }

  if (!validateEmail(email)) {
    return res.status(400).json({ error: 'Invalid email format' });
  }

  if (password.length < 8) {
    return res.status(400).json({ error: 'Password must be at least 8 characters' });
  }

  try {
    const result = await auth.signup(email, password);
    if (result.success) {
      return res.status(201).json({ token: result.token, userId: result.userId });
    }
    return res.status(400).json({ error: result.reason });
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

router.post('/login', async (req, res) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password required' });
  }

  try {
    const result = await auth.login(email, password);
    if (result.success) {
      return res.status(200).json({ token: result.token, userId: result.userId });
    }
    return res.status(401).json({ error: result.reason });
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

router.get('/me', authMiddleware, (req, res) => {
  res.json({ userId: req.userId });
});

module.exports = { router, authMiddleware };
